from heapq import heappush, heappop


def solve(n, edges, s, t):
    if s == t:
        return 0
    forward = {}
    backward = {}
    for u, v, w in edges:
        forward.setdefault(u, []).append((v, w))
        backward.setdefault(v, []).append((u, w))
    dist = [{s: 0}, {t: 0}]
    heaps = [[(0, s)], [(0, t)]]
    settled = [set(), set()]
    graphs = [forward, backward]
    mu = float('inf')
    side = 0
    while heaps[0] and heaps[1]:
        if heaps[0][0][0] + heaps[1][0][0] >= mu:
            break
        d, u = heappop(heaps[side])
        if u not in settled[side] and d <= dist[side].get(u, float('inf')):
            settled[side].add(u)
            other = 1 - side
            for v, w in graphs[side].get(u, []):
                nd = d + w
                if nd < dist[side].get(v, float('inf')):
                    dist[side][v] = nd
                    heappush(heaps[side], (nd, v))
                if v in dist[other]:
                    mu = min(mu, nd + dist[other][v])
            if u in dist[other]:
                mu = min(mu, d + dist[other][u])
        side = 1 - side
    return mu if mu != float('inf') else -1

def solve(n, edges, s, t):
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return int(dist[s][t]) if dist[s][t] != float('inf') else -1

def solve(n, edges, s, t):
    if s == t:
        return 0
    adj = [[] for _ in range(n)]
    max_w = 0
    for u, v, w in edges:
        adj[u].append((v, w))
        max_w = max(max_w, w)
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    max_dist = max_w * (n - 1)
    buckets = [[] for _ in range(max_dist + 1)]
    buckets[0].append(s)
    idx = 0
    while idx <= max_dist:
        if not buckets[idx]:
            idx += 1
            continue
        u = buckets[idx].pop()
        if dist[u] != idx:
            continue
        if u == t:
            return idx
        for v, w in adj[u]:
            nd = idx + w
            if nd <= max_dist and nd < dist[v]:
                dist[v] = nd
                buckets[nd].append(v)
    return -1 if dist[t] == INF else dist[t]
